import os
import msal

class IdentityClient:
    def __init__(self, client_id=None, tenant_id=None, client_secret=None, issuer=None):
        self.client_id = client_id or os.environ.get("AZURE_CLIENT_ID")
        self.tenant_id = tenant_id or os.environ.get("AZURE_TENANT_ID")
        self.client_secret = client_secret or os.environ.get("AZURE_CLIENT_SECRET")
        self.issuer = issuer or os.environ.get("AZURE_ISSUER")
        if not all([self.client_id, self.tenant_id, self.client_secret, self.issuer]):
            raise ValueError("Azure AD configuration missing. Ensure client_id, tenant_id, client_secret, and issuer are set.")

        self.authority = f"https://login.microsoftonline.com/{self.tenant_id}"
        self.msal_app = msal.ConfidentialClientApplication(
            self.client_id, authority=self.authority, client_credential=self.client_secret)

    def get_msal_app(self):
        return self.msal_app

    def get_config(self):
        return {
            "client_id": self.client_id,
            "tenant_id": self.tenant_id,
            "client_secret": self.client_secret,
            "issuer": self.issuer,
            "authority": self.authority
        }

from identity_client import IdentityClient
from identity_models import TokenRefreshPayload, AuthTokens

def refresh_session(payload: TokenRefreshPayload, identity_client: IdentityClient):
    msal_app = identity_client.get_msal_app()

    # MSAL's acquire_token_by_refresh_token requires a list of scopes.
    # The scopes should be the same ones for which the original access token was issued.
    # For this example, we'll use common scopes that would typically allow token refresh.
    scopes = ["User.Read", "openid", "profile", "offline_access"]

    result = msal_app.acquire_token_by_refresh_token(
        refresh_token=payload.refresh_token,
        scopes=scopes
    )

    if "access_token" in result:
        return AuthTokens(
            access_token=result["access_token"],
            refresh_token=result.get("refresh_token"),  # Refresh token might be renewed
            expires_in=result.get("expires_in")
        )
    else:
        raise RuntimeError(f"Token refresh failed: {result.get("error_description", result.get("error"))}")
